// AdminServiceServer is the server API for AdminService service.
// All implementations must embed UnimplementedAdminServiceServer
// for forward compatibility.
//
// AdminService is served by the controller for zctl day-2 backend administration
// over the same mTLS channel. It covers operations that have no CRD representation.
type AdminServiceServer interface {
	// DeleteBackend decommissions a backend by removing its offline Tailscale
	// devices from the tailnet, so a retired node does not linger in the admin
	// console. A device is the backend's when its name is the longest known
	// backend ID it matches; an online one is never deleted (stop the agent
	// first), and a backend that still runs jobs is refused unless force.
	DeleteBackend(context.Context, *DeleteBackendRequest) (*DeleteBackendResponse, error)
	// ListBackends returns the controller's live view of registered backends (type,
	// health, address, and advertised capacity). Backs `zctl get backends`; the data
	// lives in the controller's agent registry (architecture §4 BackendRegistry).
	ListBackends(context.Context, *ListBackendsRequest) (*ListBackendsResponse, error)
	// DrainBackend closes a backend to new submissions (Phase O). Jobs already
	// running on it finish untouched; new submissions are held Pending with
	// BACKEND_BUSY until the backend is uncordoned. The state persists across
	// controller restarts. Pairs with DeleteBackend: drain first, then decommission.
	DrainBackend(context.Context, *DrainBackendRequest) (*DrainBackendResponse, error)
	// UndrainBackend reopens a drained backend to new submissions.
	UndrainBackend(context.Context, *UndrainBackendRequest) (*UndrainBackendResponse, error)
	// JoinBackend mints a one-use attach token for a container that joins as a
	// backend Private to one Workspace and Named: only jobs that name it reach
	// it, never one the Scheduler places. zenthros-api asks it for the caller's
	// Workspace (workspace.backends.join); the Controller writes the token.
	JoinBackend(context.Context, *JoinBackendRequest) (*JoinBackendResponse, error)
	// RetireBackend ends a backend Private to one Workspace: its tokens are
	// revoked (it can no longer register or renew), then its access is
	// removed, then the call answers. A Public backend is never retired here.
	RetireBackend(context.Context, *RetireBackendRequest) (*RetireBackendResponse, error)
	mustEmbedUnimplementedAdminServiceServer()
}

